<script setup lang="ts">
import { computed, ref } from 'vue'; import { Github, LogIn } from 'lucide-vue-next'; import { useRoute, useRouter } from 'vue-router'; import { login, register, startGitHubLogin } from '../api/client'
const route = useRoute(); const router = useRouter(); const mode = ref<'login' | 'register'>('login'); const email = ref(''); const password = ref(''); const displayName = ref(''); const loading = ref(false); const error = ref('')
const destination = computed(() => typeof route.query.redirect === 'string' && route.query.redirect.startsWith('/') && !route.query.redirect.startsWith('//') && !route.query.redirect.startsWith('/auth') ? route.query.redirect : '/me')
async function submit() { loading.value = true; error.value = ''; try { if (mode.value === 'login') await login(email.value, password.value); else await register(email.value, password.value, displayName.value); await router.replace(destination.value) } catch (reason) { error.value = reason instanceof Error ? reason.message : '认证失败' } finally { loading.value = false } }
async function githubLogin() { error.value = ''; sessionStorage.setItem('dc_post_auth_redirect', destination.value); try { await startGitHubLogin() } catch (reason) { sessionStorage.removeItem('dc_post_auth_redirect'); error.value = reason instanceof Error ? reason.message : 'GitHub 登录暂时不可用' } }
</script>
<template><div class="auth-page"><section class="auth-copy"><span class="eyebrow">OBSERVER ACCESS</span><h1>回到你的观测席。</h1><p>保存案件进度、提交创作，与其他读者一起验证线索。</p></section><form class="auth-card" @submit.prevent="submit"><div class="auth-tabs"><button type="button" :class="{ active: mode === 'login' }" :aria-pressed="mode === 'login'" @click="mode = 'login'">登录</button><button type="button" :class="{ active: mode === 'register' }" :aria-pressed="mode === 'register'" @click="mode = 'register'">注册</button></div><label v-if="mode === 'register'">显示名称<input v-model="displayName" required minlength="2" maxlength="32" autocomplete="name" /></label><label>邮箱<input v-model="email" required type="email" autocomplete="email" /></label><label>密码<input v-model="password" required type="password" :minlength="mode === 'register' ? 12 : 1" :autocomplete="mode === 'login' ? 'current-password' : 'new-password'" /></label><p v-if="mode === 'register'" class="field-hint">至少 12 个字符，请使用独特密码。</p><p v-if="error" class="form-error" role="alert">{{ error }}</p><button class="button button-primary auth-submit" type="submit" :disabled="loading"><LogIn :size="16" /> {{ loading ? '处理中…' : mode === 'login' ? '登录' : '创建账号' }}</button><div class="auth-divider"><span>或</span></div><button class="button button-quiet auth-submit" type="button" :disabled="loading" @click="githubLogin"><Github :size="17" /> 使用 GitHub 登录</button></form></div></template>
